    @Override public void itemStateChanged(ItemEvent e) {
        Object source = e.getSource();
        if (source == scale1x || source == scale2x || source == scale3x) {
            // Pouze aktualizuj zvětšení a nech pack/repaint zařídit vizuální změnu
            updateMagnification();
        } else {
            // Ostatní změny (ColorMode, Interlace, DitherMode atd.)
            if (source == colorModeChoice || source == interlaceCheckbox) {
                updateComponentVisibility(); // Aktualizuj UI layout, pokud je třeba
            }
            // Vždy spusť aktualizaci náhledu pro změny jiné než zoom
             triggerPreviewUpdate();
        }
    }
