    // --- Actions ---
    private void loadPaletteAction() { /* ... Same as before ... */ IJ.log("Load Palette button clicked."); JFileChooser fileChooser = new JFileChooser(paletteFilePath); FileNameExtensionFilter filter = new FileNameExtensionFilter("Palette Files (*.pal, *.txt, *.csv)", "pal", "txt", "csv"); fileChooser.setFileFilter(filter); int returnVal = fileChooser.showOpenDialog(this); if (returnVal == JFileChooser.APPROVE_OPTION) { File file = fileChooser.getSelectedFile(); paletteFilePath = file.getAbsolutePath(); boolean loaded = loadPaletteFromFile(paletteFilePath); if (loaded) { IJ.log("Palette loaded successfully, setting mode to Custom and updating preview."); colorModeChoice.select(ColorMode.CUSTOM.toString()); updateComponentVisibility(); triggerPreviewUpdate(); } } else { IJ.log("Load Palette canceled."); } }
    private void applyChangesAction() { /* ... Same as before ... */ IJ.log("Apply button clicked."); if (sourceImp == null) return; if (!readBlockSizeUISettings()) { IJ.error("Cannot apply changes. Invalid block size detected."); return; } readUISettings(); IJ.log(String.format("ApplyAction: Block=%dx%d Interlace=%b Dither=%s Color=%s DLevel=%.2f BCG=%.1f/%.1f/%.1f", this.blockSizeX, this.blockSizeY, this.isInterlaceEnabled, this.ditheringMode, this.colorMode, this.ditheringLevel, this.brightness, this.contrast, this.gamma)); if (this.colorMode == ColorMode.USER_DEFINED) { IJ.log(" Apply User Defined: PaperA=" + paperASelection + " InkA=" + inkASelection + (isInterlaceEnabled ? (" PaperB=" + paperBSelection + " InkB=" + inkBSelection) : "")); } Color[] applyPalette = getActivePalette(); ImageProcessor ipToProcess = sourceImp.getProcessor(); ImageProcessor backupIp = ipToProcess.duplicate(); try { IJ.showStatus("Applying ZX Spectrum Conversion..."); processImage(ipToProcess, this.blockSizeX, this.blockSizeY, this.isInterlaceEnabled, this.ditheringMode, this.colorMode, applyPalette, this.customPalette, this.paperASelection, this.inkASelection, this.paperBSelection, this.inkBSelection, this.ditheringLevel, this.brightness, this.contrast, this.gamma, this.brightAttributeThreshold); sourceImp.updateAndDraw(); IJ.showStatus("Applied ZX Spectrum Conversion."); } catch (Exception e) { IJ.error("Error applying changes: " + e.getMessage()); sourceImp.setProcessor(backupIp); sourceImp.updateAndDraw(); IJ.showStatus("Error applying changes. Original restored."); e.printStackTrace(); } }

    /** Reads and validates Block Size X and Y from the UI TextFields. */
    private boolean readBlockSizeUISettings() { /* ... Same as before ... */ int oldX = blockSizeX; int oldY = blockSizeY; int newX = oldX; int newY = oldY; boolean xValid = true; boolean yValid = true; try { newX = Integer.parseInt(blockSizeXField.getText()); if (newX < 1) { IJ.log("Warning: Block Size X must be >= 1. Reverting to " + oldX); blockSizeXField.setText(String.valueOf(oldX)); newX = oldX; xValid = false; } } catch (NumberFormatException e) { IJ.log("Warning: Invalid number for Block Size X. Reverting to " + oldX); blockSizeXField.setText(String.valueOf(oldX)); newX = oldX; xValid = false; } try { newY = Integer.parseInt(blockSizeYField.getText()); if (newY < 1) { IJ.log("Warning: Block Size Y must be >= 1. Reverting to " + oldY); blockSizeYField.setText(String.valueOf(oldY)); newY = oldY; yValid = false; } } catch (NumberFormatException e) { IJ.log("Warning: Invalid number for Block Size Y. Reverting to " + oldY); blockSizeYField.setText(String.valueOf(oldY)); newY = oldY; yValid = false; } blockSizeX = newX; blockSizeY = newY; return xValid && yValid; }

    /** Reads all UI settings into member variables. Assumes block size is already validated. */
    private void readUISettings() { /* ... Same as before ... */ ditheringMode = DitheringMode.fromString(ditherModeChoice.getSelectedItem()); colorMode = ColorMode.fromString(colorModeChoice.getSelectedItem()); isInterlaceEnabled = interlaceCheckbox.getState(); if (colorMode == ColorMode.USER_DEFINED) { paperASelection = parseUserDefinedColors(paperAField.getText()); inkASelection = parseUserDefinedColors(inkAField.getText()); if (isInterlaceEnabled) { paperBSelection = parseUserDefinedColors(paperBField.getText()); inkBSelection = parseUserDefinedColors(inkBField.getText()); } else { paperBSelection = UserColorSelection.empty(); inkBSelection = UserColorSelection.empty(); } } else { paperASelection = UserColorSelection.empty(); inkASelection = UserColorSelection.empty(); paperBSelection = UserColorSelection.empty(); inkBSelection = UserColorSelection.empty(); } ditheringLevel = ditherScroll.getValue() / 100.0; brightness = brightScroll.getValue() / 100.0; contrast = contrastScroll.getValue() / 100.0; gamma = Math.max(0.01, gammaScroll.getValue() / 100.0); if (this.colorMode == ColorMode.CUSTOM && (this.customPalette == null || this.customPalette.length == 0)) { if (!paletteFilePath.isEmpty()) { IJ.log("Warning: Custom mode selected but no valid palette loaded. Reverting to ZX_NORMAL."); this.colorMode = ColorMode.ZX_NORMAL; colorModeChoice.select(ColorMode.ZX_NORMAL.toString()); updateComponentVisibility(); paletteFilePath = ""; } } }

    /** Parses the user input string for color indexes and bright mode flags. */
    private UserColorSelection parseUserDefinedColors(String text) { /* ... Same as before ... */ java.util.List<Integer> indexes = new java.util.ArrayList<>(); BrightMode brightMode = BrightMode.OFF; boolean foundB_lower = false; boolean foundB_upper = false; if (text != null && !text.trim().isEmpty()) { if (text.contains("B")) { foundB_upper = true; } else if (text.contains("b")) { foundB_lower = true; } String cleanText = text; if (foundB_upper) cleanText = cleanText.replace('B', ','); if (foundB_lower) cleanText = cleanText.replace('b', ','); String[] parts = cleanText.replaceAll("[^0-7,]", "").split(","); for (String part : parts) { part = part.trim(); if (!part.isEmpty()) { try { int index = Integer.parseInt(part); if (index >= 0 && index <= 7) { indexes.add(index); } } catch (NumberFormatException e) { } } } } if (foundB_upper) brightMode = BrightMode.FORCED; else if (foundB_lower) brightMode = BrightMode.ALLOWED; java.util.List<Integer> uniqueIndexes = new java.util.ArrayList<>(new LinkedHashSet<>(indexes)); return new UserColorSelection(uniqueIndexes, brightMode); }

     /** Determines the effective BrightMode for a block based on Paper and Ink selections. */
    private BrightMode determineBlockBrightMode(UserColorSelection paperSelection, UserColorSelection inkSelection) { /* ... Same as before ... */ if (paperSelection.brightMode == BrightMode.FORCED || inkSelection.brightMode == BrightMode.FORCED) { return BrightMode.FORCED; } else if (paperSelection.brightMode == BrightMode.ALLOWED || inkSelection.brightMode == BrightMode.ALLOWED) { return BrightMode.ALLOWED; } else { return BrightMode.OFF; } }

    // ******** UPDATED updateMagnification (Rely on ImageCanvas sizing) ********
     private void updateMagnification() {
         if (sourceCanvas == null || previewCanvas == null || scaleGroup == null || imagePanel == null || sourceImp == null) { IJ.log("updateMagnification skipped: UI not ready."); return; }
         Checkbox selected = scaleGroup.getSelectedCheckbox(); double newMag = 1.0; if (selected == scale2x) newMag = 2.0; else if (selected == scale3x) newMag = 3.0;
         if (newMag != currentMagnification) {
             IJ.log("Setting Magnification from " + currentMagnification + " to " + newMag);
             sourceCanvas.setMagnification(newMag); previewCanvas.setMagnification(newMag); currentMagnification = newMag;
             imagePanel.invalidate(); displayPanel.invalidate(); this.pack();
             sourceCanvas.repaint(); previewCanvas.repaint();
             IJ.log("Magnification update finished.");
         }
     }
