    // --- Trigger Preview Update ---
    private void triggerPreviewUpdate() { /* ... Same as before ... */ if (sourceImp == null || previewImp == null || !isVisible()) { return; } if (!readBlockSizeUISettings()) { IJ.log("Preview update skipped due to invalid block size."); ImageProcessor errorIp = previewImp.getProcessor(); if (errorIp != null) { errorIp.setColor(Color.RED); errorIp.fill(); errorIp.setColor(Color.WHITE); errorIp.drawString("Invalid Block Size!", 10, 20); previewImp.updateAndDraw(); } return; } readUISettings(); Color[] ditherPal = getActivePalette(); if (colorMode == ColorMode.USER_DEFINED) { ditherPal = zxPaletteNormal; if (paperASelection.indexes.isEmpty() && inkASelection.indexes.isEmpty()) { ditherPal = bwPalette; } } else if (colorMode == ColorMode.CUSTOM) { ditherPal = this.customPalette; if (ditherPal == null || ditherPal.length == 0) { ditherPal = bwPalette; } } PreviewParameters params = new PreviewParameters( sourceImp.getProcessor(), blockSizeX, blockSizeY, ditheringMode, colorMode, ditherPal, customPalette, ditheringLevel, brightness, contrast, gamma, brightAttributeThreshold, isInterlaceEnabled, paperASelection, inkASelection, paperBSelection, inkBSelection ); if (currentWorker != null && !currentWorker.isDone()) { IJ.log("Cancelling previous preview worker (Hash: " + currentWorker.hashCode() + ")"); currentWorker.cancel(true); } IJ.log("Starting new preview worker..."); currentWorker = new PreviewWorker(params); currentWorker.execute(); }

    // --- Core Image Processing Method ---
    void processImage(ImageProcessor ip, int blockX, int blockY, boolean interlaceEnabled, DitheringMode dMode, ColorMode cMode, Color[] activePal, Color[] custPal, UserColorSelection pA, UserColorSelection iA, UserColorSelection pB, UserColorSelection iB, double dLevel, double bright, double cont, double gam, double brightThresh) { /* ... Same as before ... */ BufferedImage bufferedImage = ip.getBufferedImage(); BufferedImage adjustedImage = applyBCG(bufferedImage, bright, cont, gam); BufferedImage finalImage; if (interlaceEnabled) { IJ.log("Processing Interlaced Mode..."); finalImage = processInterlaceModeNew(adjustedImage, blockX, blockY, dMode, cMode, activePal, custPal, pA, iA, pB, iB, dLevel, brightThresh); } else { IJ.log("Processing Non-Interlaced Mode..."); Color[] paletteForDithering = activePal; if (cMode == ColorMode.USER_DEFINED) { paletteForDithering = zxPaletteNormal; if (pA.indexes.isEmpty() && iA.indexes.isEmpty()) paletteForDithering = bwPalette; } else if (cMode == ColorMode.CUSTOM) { paletteForDithering = custPal != null && custPal.length > 0 ? custPal : bwPalette; } BufferedImage ditheredImage = applyDithering(adjustedImage, dMode, paletteForDithering, dLevel); finalImage = convertToZXSpectrum(adjustedImage, ditheredImage, blockX, blockY, cMode, pA, iA, brightThresh, paletteForDithering); } if (finalImage.getType() == BufferedImage.TYPE_INT_RGB && ip instanceof ColorProcessor) { int[] pixels = ((DataBufferInt) finalImage.getRaster().getDataBuffer()).getData(); ip.setPixels(pixels); } else { ImagePlus tempImp = new ImagePlus("", finalImage); ImageProcessor tempIp = tempImp.getProcessor(); ip.insert(tempIp, 0, 0); } }

