     /** Helper method to get actual palette colors based on BrightMode and indexes */
     List<Color> getPaletteColors(BrightMode effectiveBlockBrightMode, List<Integer> indexes) { /* ... Same as before ... */ List<Color> result = new ArrayList<>(); Color[] sourcePalette; if (effectiveBlockBrightMode == BrightMode.FORCED) { sourcePalette = zxPaletteBright; } else { sourcePalette = zxPaletteNormal; } if (indexes == null || indexes.isEmpty()) { result.addAll(Arrays.asList(sourcePalette)); } else { for (int index : indexes) { if (index >= 0 && index < sourcePalette.length) { if (!result.contains(sourcePalette[index])) { result.add(sourcePalette[index]); } } } } if (result.isEmpty()) { IJ.log("Warning: getPaletteColors resulted in empty list for block. Adding default Black."); result.add(sourcePalette[0]); } return result; }

