    // --- BCG and Dithering Methods ---
    BufferedImage applyBCG(BufferedImage i, double br, double co, double ga) { /* ... Same as before ... */ float cF=(float)co;float off=(float)(128.0*(1.0-cF)+255.0*(br-1.0));RescaleOp rO=new RescaleOp(cF,off,null);BufferedImage cBI=rO.filter(i,null);if(Math.abs(ga-1.0)>1e-6){LookupTable lT=createGammaLookupTable(ga);LookupOp gO=new LookupOp(lT,null);return gO.filter(cBI,null);}else{return cBI;} }
    LookupTable createGammaLookupTable(double ga) { /* ... Same as before ... */ if(ga<=0)ga=0.01;short[] gL=new short[256];double exp=1.0/ga;for(int i=0;i<256;i++)gL[i]=(short)Math.min(255,(int)(255.0*Math.pow(i/255.0,exp)+0.5));short[][] lD=new short[3][256];for(int i=0;i<3;i++)System.arraycopy(gL,0,lD[i],0,256);return new ShortLookupTable(0,lD); }
    BufferedImage applyDithering(BufferedImage i, DitheringMode m, Color[] p, double l) { /* ... Same as before ... */ if(p==null||p.length==0){p=bwPalette;}if(l<=0)m=null;int w=i.getWidth(),h=i.getHeight();BufferedImage dI=new BufferedImage(w,h,BufferedImage.TYPE_INT_RGB);Graphics2D g2=dI.createGraphics();g2.drawImage(i,0,0,null);g2.dispose();DitheringMode eM=(m!=null)?m:DitheringMode.FLOYD_STEINBERG;switch(eM){case FLOYD_STEINBERG: if(l<=0)break;return floydSteinbergDitherProcess(dI,p,l);case ATKINSON: if(l<=0)break;return atkinsonDitherProcess(dI,p,l);case JARVIS_JUDICE_NINKE: if(l<=0)break;return jjnDitherProcess(dI,p,l);case BAYER_2X2:case BAYER_4X4:case BAYER_8X8: if(l<=0)break;return bayerDitherProcess(dI,m.getBayerSize(),p,l);case HALFTONE: if(l<=0)break;return halftoneDitherProcess(dI,p,l);default:break;}BufferedImage q=new BufferedImage(w,h,BufferedImage.TYPE_INT_RGB);for(int y=0;y<h;y++){for(int x=0;x<w;x++){q.setRGB(x,y,findClosestColor(new Color(i.getRGB(x,y)),p).getRGB());}}return q; }

    // --- Specific Dithering Algorithms (Compacted) ---
    BufferedImage floydSteinbergDitherProcess(BufferedImage i, Color[] t, double l) { /* ... Same as before ... */ int w=i.getWidth(),h=i.getHeight();float dF=(float)l;float[] eR=new float[w],eG=new float[w],eB=new float[w],nER=new float[w],nEG=new float[w],nEB=new float[w];for(int y=0;y<h;y++){Arrays.fill(nER,0f);Arrays.fill(nEG,0f);Arrays.fill(nEB,0f);float pER=0,pEG=0,pEB=0;for(int x=0;x<w;x++){Color oC=new Color(i.getRGB(x,y));int oR=clamp(oC.getRed()+(int)(eR[x]+pER+0.5f));int oG=clamp(oC.getGreen()+(int)(eG[x]+pEG+0.5f));int oB=clamp(oC.getBlue()+(int)(eB[x]+pEB+0.5f));Color clC=findClosestColor(new Color(oR,oG,oB),t);i.setRGB(x,y,clC.getRGB());float errR=(oR-clC.getRed())*dF;float errG=(oG-clC.getGreen())*dF;float errB=(oB-clC.getBlue())*dF;pER=errR*7f/16f;pEG=errG*7f/16f;pEB=errB*7f/16f;if(x>0){nER[x-1]+=errR*3f/16f;nEG[x-1]+=errG*3f/16f;nEB[x-1]+=errB*3f/16f;}nER[x]+=errR*5f/16f;nEG[x]+=errG*5f/16f;nEB[x]+=errB*5f/16f;if(x<w-1){nER[x+1]+=errR*1f/16f;nEG[x+1]+=errG*1f/16f;nEB[x+1]+=errB*1f/16f;}}System.arraycopy(nER,0,eR,0,w);System.arraycopy(nEG,0,eG,0,w);System.arraycopy(nEB,0,eB,0,w);}return i;}
    BufferedImage atkinsonDitherProcess(BufferedImage i, Color[] t, double l) { /* ... Same as before ... */ int w=i.getWidth(),h=i.getHeight();float dF=(float)l/8.0f;float[] eR=new float[w+2],eG=new float[w+2],eB=new float[w+2],nER=new float[w+2],nEG=new float[w+2],nEB=new float[w+2],nnER=new float[w+2],nnEG=new float[w+2],nnEB=new float[w+2];for(int y=0;y<h;y++){System.arraycopy(nER,0,eR,0,w+2);System.arraycopy(nEG,0,eG,0,w+2);System.arraycopy(nEB,0,eB,0,w+2);System.arraycopy(nnER,0,nER,0,w+2);System.arraycopy(nnEG,0,nEG,0,w+2);System.arraycopy(nnEB,0,nEB,0,w+2);Arrays.fill(nnER,0f);Arrays.fill(nnEG,0f);Arrays.fill(nnEB,0f);int idx;for(int x=0;x<w;x++){idx=x+1;Color oC=new Color(i.getRGB(x,y));int oR=clamp(oC.getRed()+(int)(eR[idx]+0.5f));int oG=clamp(oC.getGreen()+(int)(eG[idx]+0.5f));int oB=clamp(oC.getBlue()+(int)(eB[idx]+0.5f));Color clC=findClosestColor(new Color(oR,oG,oB),t);i.setRGB(x,y,clC.getRGB());float errR=(oR-clC.getRed())*dF;float errG=(oG-clC.getGreen())*dF;float errB=(oB-clC.getBlue())*dF;if(idx+1<eR.length){eR[idx+1]+=errR;eG[idx+1]+=errG;eB[idx+1]+=errB;}if(idx+2<eR.length){eR[idx+2]+=errR;eG[idx+2]+=errG;eB[idx+2]+=errB;}if(idx-1>=0){nER[idx-1]+=errR;nEG[idx-1]+=errG;nEB[idx-1]+=errB;}nER[idx]+=errR;nEG[idx]+=errG;nEB[idx]+=errB;if(idx+1<nER.length){nER[idx+1]+=errR;nEG[idx+1]+=errG;nEB[idx+1]+=errB;}nnER[idx]+=errR;nnEG[idx]+=errG;nnEB[idx]+=errB;}}return i;}
    BufferedImage jjnDitherProcess(BufferedImage i, Color[] t, double l) { /* ... Same as before ... */ int w=i.getWidth(),h=i.getHeight();float dF=(float)l/48.0f;float[] eR=new float[w+4],eG=new float[w+4],eB=new float[w+4],nER=new float[w+4],nEG=new float[w+4],nEB=new float[w+4],nnER=new float[w+4],nnEG=new float[w+4],nnEB=new float[w+4];for(int y=0;y<h;y++){System.arraycopy(nER,0,eR,0,w+4);System.arraycopy(nEG,0,eG,0,w+4);System.arraycopy(nEB,0,eB,0,w+4);System.arraycopy(nnER,0,nER,0,w+4);System.arraycopy(nnEG,0,nEG,0,w+4);System.arraycopy(nnEB,0,nEB,0,w+4);Arrays.fill(nnER,0f);Arrays.fill(nnEG,0f);Arrays.fill(nnEB,0f);int idx;for(int x=0;x<w;x++){idx=x+2;Color oC=new Color(i.getRGB(x,y));int oR=clamp(oC.getRed()+(int)(eR[idx]+0.5f));int oG=clamp(oC.getGreen()+(int)(eG[idx]+0.5f));int oB=clamp(oC.getBlue()+(int)(eB[idx]+0.5f));Color clC=findClosestColor(new Color(oR,oG,oB),t);i.setRGB(x,y,clC.getRGB());float errR=(oR-clC.getRed())*dF;float errG=(oG-clC.getGreen())*dF;float errB=(oB-clC.getBlue())*dF;if(idx+1<eR.length){eR[idx+1]+=errR*7f;eG[idx+1]+=errG*7f;eB[idx+1]+=errB*7f;}if(idx+2<eR.length){eR[idx+2]+=errR*5f;eG[idx+2]+=errG*5f;eB[idx+2]+=errB*5f;}if(idx-2>=0){nER[idx-2]+=errR*3f;nEG[idx-2]+=errG*3f;nEB[idx-2]+=errB*3f;}if(idx-1>=0){nER[idx-1]+=errR*5f;nEG[idx-1]+=errG*5f;nEB[idx-1]+=errB*5f;}nER[idx]+=errR*7f;nEG[idx]+=errG*7f;nEB[idx]+=errB*7f;if(idx+1<nER.length){nER[idx+1]+=errR*5f;nEG[idx+1]+=errG*5f;nEB[idx+1]+=errB*5f;}if(idx+2<nER.length){nER[idx+2]+=errR*3f;nEG[idx+2]+=errG*3f;nEB[idx+2]+=errB*3f;}if(idx-2>=0){nnER[idx-2]+=errR*1f;nnEG[idx-2]+=errG*1f;nnEB[idx-2]+=errB*1f;}if(idx-1>=0){nnER[idx-1]+=errR*3f;nnEG[idx-1]+=errG*3f;nnEB[idx-1]+=errB*3f;}nnER[idx]+=errR*5f;nnEG[idx]+=errG*5f;nnEB[idx]+=errB*5f;if(idx+1<nnER.length){nnER[idx+1]+=errR*3f;nnEG[idx+1]+=errG*3f;nnEB[idx+1]+=errB*3f;}if(idx+2<nnER.length){nnER[idx+2]+=errR*1f;nnEG[idx+2]+=errG*1f;nnEB[idx+2]+=errB*1f;}}}return i;}
    int clamp(float value) { return Math.max(0, Math.min(255, (int)(value + 0.5f))); }
    int clamp(int value) { return Math.max(0, Math.min(255, value)); }
    BufferedImage bayerDitherProcess(BufferedImage i, int n, Color[] t, double l) { /* ... Same as before ... */ int w=i.getWidth(),h=i.getHeight();BufferedImage o=new BufferedImage(w,h,BufferedImage.TYPE_INT_RGB);int[][] m=getBayerMatrix(n);int aN=m.length;float dF=(float)l;float tD=(float)(aN*aN);for(int y=0;y<h;y++){for(int x=0;x<w;x++){Color oC=new Color(i.getRGB(x,y));float T=(m[y%aN][x%aN]/tD)*255f*dF;int r=clamp(oC.getRed()+(int)(T-(127.5f*dF)+0.5f));int g=clamp(oC.getGreen()+(int)(T-(127.5f*dF)+0.5f));int b=clamp(oC.getBlue()+(int)(T-(127.5f*dF)+0.5f));o.setRGB(x,y,findClosestColor(new Color(r,g,b),t).getRGB());}}return o;}
    BufferedImage halftoneDitherProcess(BufferedImage i, Color[] t, double l) { /* ... Same as before ... */ int w=i.getWidth(),h=i.getHeight();BufferedImage o=new BufferedImage(w,h,BufferedImage.TYPE_INT_RGB);float dF=(float)l;for(int y=0;y<h;y++){for(int x=0;x<w;x++){Color oC=new Color(i.getRGB(x,y));float tO=((x+y)%2==0)?(128f*dF):(-128f*dF);int r=clamp(oC.getRed()+(int)(tO+0.5f));int g=clamp(oC.getGreen()+(int)(tO+0.5f));int b=clamp(oC.getBlue()+(int)(tO+0.5f));o.setRGB(x,y,findClosestColor(new Color(r,g,b),t).getRGB());}}return o;}

    // --- Bayer Matrix Generation ---
    private static final int[][] BAYER_MATRIX_2X2 = { {0,2}, {3,1} }; /* ... Definitions ... */
    private static final int[][] BAYER_MATRIX_4X4 = { {0,8,2,10}, {12,4,14,6}, {3,11,1,9}, {15,7,13,5} };
    private static final int[][] BAYER_MATRIX_8X8 = { { 0,32, 8,40, 2,34,10,42}, {48,16,56,24,50,18,58,26}, {12,44, 4,36,14,46, 6,38}, {60,28,52,20,62,30,54,22}, { 3,35,11,43, 1,33, 9,41}, {51,19,59,27,49,17,57,25}, {15,47, 7,39,13,45, 5,37}, {63,31,55,23,61,29,53,21} };
    int[][] getBayerMatrix(int N) { /* ... Same as before ... */ switch (N) { case 2: return BAYER_MATRIX_2X2; case 4: return BAYER_MATRIX_4X4; case 8: return BAYER_MATRIX_8X8; default: IJ.log("Warning: Bayer matrix size " + N + " invalid. Using 4x4."); return BAYER_MATRIX_4X4; } }

    // --- Non-Interlaced Block Processing Wrapper ---
    BufferedImage convertToZXSpectrum(BufferedImage adjustedImage, BufferedImage ditheredImage, int blockWidth, int blockHeight, ColorMode cMode, UserColorSelection paperA, UserColorSelection inkA, double brightThresh, Color[] ditherPalette) { /* ... Same as before ... */ int width = ditheredImage.getWidth(), height = ditheredImage.getHeight(); BufferedImage zxImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB); if (blockWidth <= 1 && blockHeight <= 1) { IJ.log("Attributes disabled (block size 1x1). Applying dithered result directly."); Graphics2D g = zxImage.createGraphics(); g.drawImage(ditheredImage, 0, 0, null); g.dispose(); return zxImage; } for (int yStart = 0; yStart < height; yStart += blockHeight) { for (int xStart = 0; xStart < width; xStart += blockWidth) { processBlock(adjustedImage, ditheredImage, zxImage, xStart, yStart, blockWidth, blockHeight, cMode, paperA, inkA, brightThresh, ditherPalette); } } return zxImage; }

    /** Processes a single block for non-interlaced output (Handles USER_DEFINED Option 1) */
    void processBlock(BufferedImage adjustedImage, BufferedImage ditheredImage, BufferedImage outputImage, int startX, int startY, int blockWidth, int blockHeight, ColorMode cMode, UserColorSelection paperA, UserColorSelection inkA, double brightThresh, Color[] ditherPalette) { /* ... Same as before (with Option 1 logic) ... */ int endX = Math.min(startX + blockWidth, ditheredImage.getWidth()); int endY = Math.min(startY + blockHeight, ditheredImage.getHeight()); if (startX >= endX || startY >= endY) return; BrightMode blockBrightMode = BrightMode.OFF; Color[] blockPaletteNormal = zxPaletteNormal; Color[] blockPaletteBright = zxPaletteBright; if (cMode == ColorMode.USER_DEFINED) { blockBrightMode = determineBlockBrightMode(paperA, inkA); if (blockBrightMode == BrightMode.ALLOWED) { double totalIntensity = 0; int pixelCount = 0; for (int y = startY; y < endY; y++) { for (int x = startX; x < endX; x++) { Color adjColor = new Color(adjustedImage.getRGB(x, y)); totalIntensity += (adjColor.getRed() + adjColor.getGreen() + adjColor.getBlue()) / 3.0; pixelCount++; } } if (pixelCount > 0 && (totalIntensity / pixelCount) >= brightThresh) { blockBrightMode = BrightMode.FORCED; } else { blockBrightMode = BrightMode.OFF; } } } else if (cMode == ColorMode.ZX_BRIGHT_ATTRIBUTE) { double totalIntensity = 0; int pixelCount = 0; for (int y = startY; y < endY; y++) { for (int x = startX; x < endX; x++) { Color adjColor = new Color(adjustedImage.getRGB(x, y)); totalIntensity += (adjColor.getRed() + adjColor.getGreen() + adjColor.getBlue()) / 3.0; pixelCount++; } } if (pixelCount > 0 && (totalIntensity / pixelCount) >= brightThresh) { blockBrightMode = BrightMode.FORCED; } else { blockBrightMode = BrightMode.OFF; } } Color[] finalBlockPalette = (blockBrightMode == BrightMode.FORCED) ? blockPaletteBright : blockPaletteNormal; Color finalInk = Color.BLACK; Color finalPaper = Color.WHITE; if (cMode == ColorMode.USER_DEFINED) { List<Color> allowedPaperColors = getPaletteColors(blockBrightMode, paperA.indexes); List<Color> allowedInkColors = getPaletteColors(blockBrightMode, inkA.indexes); if (allowedInkColors.isEmpty()){ finalInk = finalBlockPalette[0];} if (allowedPaperColors.isEmpty()){ finalPaper = findClosestDifferentPaletteColor(finalInk, finalBlockPalette);} Set<Color> allowedBlockSet = new LinkedHashSet<>(allowedInkColors); allowedBlockSet.addAll(allowedPaperColors); List<Color> allowedBlockColors = new ArrayList<>(allowedBlockSet); Map<Color, Integer> colorCounts = new HashMap<>(); if (!allowedBlockColors.isEmpty()) { for (int y = startY; y < endY; y++) { for (int x = startX; x < endX; x++) { Color ditheredPixelColor = new Color(ditheredImage.getRGB(x, y)); Color closestAllowed = findClosestColor(ditheredPixelColor, allowedBlockColors); colorCounts.put(closestAllowed, colorCounts.getOrDefault(closestAllowed, 0) + 1); } } } List<Map.Entry<Color, Integer>> sortedCounts = new ArrayList<>(colorCounts.entrySet()); sortedCounts.sort((e1, e2) -> e2.getValue().compareTo(e1.getValue())); finalInk = null; for (Map.Entry<Color, Integer> entry : sortedCounts) { if (allowedInkColors.contains(entry.getKey())) { finalInk = entry.getKey(); break; } } if (finalInk == null) { finalInk = !allowedInkColors.isEmpty() ? allowedInkColors.get(0) : finalBlockPalette[0]; } finalPaper = null; for (Map.Entry<Color, Integer> entry : sortedCounts) { Color potentialPaper = entry.getKey(); if (!potentialPaper.equals(finalInk) && allowedPaperColors.contains(potentialPaper)) { finalPaper = potentialPaper; break; } } if (finalPaper == null) { finalPaper = findClosestDifferentPaletteColor(finalInk, allowedPaperColors); if (finalPaper.equals(finalInk)) { finalPaper = findClosestDifferentPaletteColor(finalInk, finalBlockPalette); } } } else { Map<Color, Integer> colorCounts = new HashMap<>(); for (int y = startY; y < endY; y++) { for (int x = startX; x < endX; x++) { Color ditheredPixelColor = new Color(ditheredImage.getRGB(x, y)); Color closestInBlockPalette = findClosestColor(ditheredPixelColor, finalBlockPalette); colorCounts.put(closestInBlockPalette, colorCounts.getOrDefault(closestInBlockPalette, 0) + 1); } } if (!colorCounts.isEmpty()) { java.util.List<Map.Entry<Color, Integer>> entryList = new java.util.ArrayList<>(colorCounts.entrySet()); entryList.sort((e1, e2) -> e2.getValue().compareTo(e1.getValue())); finalInk = entryList.get(0).getKey(); if (entryList.size() > 1) { finalPaper = entryList.get(1).getKey(); if (finalPaper.equals(finalInk)) { finalPaper = findClosestDifferentPaletteColor(finalInk, finalBlockPalette); } } else { finalPaper = findClosestDifferentPaletteColor(finalInk, finalBlockPalette); } } else { finalInk = finalBlockPalette.length > 0 ? finalBlockPalette[0] : Color.BLACK; finalPaper = findClosestDifferentPaletteColor(finalInk, finalBlockPalette); } } for (int y = startY; y < endY; y++) { for (int x = startX; x < endX; x++) { Color ditheredPixelColor = new Color(ditheredImage.getRGB(x, y)); double distInk = colorDistanceSq(ditheredPixelColor, finalInk); double distPaper = colorDistanceSq(ditheredPixelColor, finalPaper); outputImage.setRGB(x, y, (distInk <= distPaper) ? finalInk.getRGB() : finalPaper.getRGB()); } } }

    // --- Color Utility Methods ---
    // ******** REMOVED DUPLICATE DEFINITION ********
    Color getBrightColor(Color n){ if(n==null)return Color.BLACK; for(int i=0;i<zxPaletteNormal.length;i++)if(zxPaletteNormal[i].equals(n))return zxPaletteBright[i]; return n;}
    Color findClosestDifferentPaletteColor(Color i, Color[] t){ Color c=i;double m=Double.MAX_VALUE;boolean f=false;if(t==null||t.length<2)return c;for(Color p:t){if(p.equals(i))continue;f=true;double d=colorDistance(i,p);if(d<m){m=d;c=p;}}return c;}
    Color findClosestDifferentPaletteColor(Color i, List<Color> t){ if(t==null||t.isEmpty())return i; Color[] p=t.toArray(new Color[0]); if(p.length<1)return i; return findClosestDifferentPaletteColor(i,p); }
    double colorDistanceSq(Color c1, Color c2){ long dr=c1.getRed()-c2.getRed();long dg=c1.getGreen()-c2.getGreen();long db=c1.getBlue()-c2.getBlue(); return dr*dr+dg*dg+db*db; }
    double colorDistance(Color c1, Color c2){ return Math.sqrt(colorDistanceSq(c1, c2)); }
    Color findClosestColor(Color i, Color[] t){ if(t==null||t.length==0)return Color.BLACK; Color c=t[0];double m=colorDistanceSq(i,c);for(int j=1;j<t.length;j++){if(m==0)break; Color p=t[j];double d=colorDistanceSq(i,p);if(d<m){m=d;c=p;}}return c; }
    Color findClosestColor(Color i, List<Color> t){ if(t==null||t.isEmpty())return Color.BLACK; Color[] p=t.toArray(new Color[0]); if(p.length<1)return Color.BLACK; return findClosestColor(i,p); }

    // --- Palette Loading ---
    boolean loadPaletteFromFile(String filePath) { /* ... Same as before ... */ java.util.List<Color> loadedPalette = new java.util.ArrayList<>(); try (BufferedReader br = new BufferedReader(new FileReader(filePath))) { String line; int lineNum = 0; while ((line = br.readLine()) != null) { lineNum++; line = line.trim(); if (line.isEmpty() || line.startsWith("#") || line.startsWith(";") || line.startsWith("//")) continue; String[] values = line.split("[,\\s]+"); if (values.length >= 3) { try { int r = clamp(Integer.parseInt(values[0].trim())); int g = clamp(Integer.parseInt(values[1].trim())); int b = clamp(Integer.parseInt(values[2].trim())); loadedPalette.add(new Color(r, g, b)); } catch (NumberFormatException nfe) { IJ.log("Warning: Invalid number format on line " + lineNum + ": " + line); } } else { IJ.log("Warning: Skipping malformed line " + lineNum + " (needs R, G, B): " + line); } } if (!loadedPalette.isEmpty()) { this.customPalette = loadedPalette.toArray(new Color[0]); IJ.log("Loaded " + this.customPalette.length + " colors from " + new File(filePath).getName()); return true; } else { IJ.error("Palette Loading", "No valid colors found in file: " + filePath); this.customPalette = null; return false; } } catch (IOException ex) { IJ.error("Palette Loading Error", "Error reading file:\n" + ex.getMessage()); this.customPalette = null; return false; } }

    // --- Helper Methods for Active Palette ---
    public Color[] getActivePalette() { /* ... Same as before ... */ switch (this.colorMode) { case ZX_NORMAL: case ZX_BRIGHT_ATTRIBUTE: return zxPaletteNormal; case C64: return c64Palette; case EGA: return egaPalette; case BLACK_AND_WHITE: return bwPalette; case BLACK_RED_GREEN_WHITE: return brgwPalette; case USER_DEFINED: return zxPaletteNormal; case CUSTOM: return (this.customPalette != null && this.customPalette.length > 0) ? this.customPalette : bwPalette; default: return zxPaletteNormal; } }
     String colorToName(Color c) { /* ... Same as before ... */ if(c==null)return"null"; for(int i=0; i<zxPaletteNormal.length; i++) if(zxPaletteNormal[i].equals(c)) return "ZXN"+i; for(int i=0; i<zxPaletteBright.length; i++) if(zxPaletteBright[i].equals(c)) return "ZXB"+i; return String.format("RGB(%d,%d,%d)", c.getRed(), c.getGreen(), c.getBlue()); }

    // --- UI Component Visibility Update ---
    private void updateComponentVisibility() { /* ... Same as before ... */ if (colorModeChoice == null || userDefinedPanel == null || interlaceCheckbox == null || paperBLabel == null || paperBField == null || inkBLabel == null || inkBField == null) { return; } ColorMode selectedMode = ColorMode.fromString(colorModeChoice.getSelectedItem()); boolean showUserDefined = (selectedMode == ColorMode.USER_DEFINED); boolean needsResize = false; if (userDefinedPanel.isVisible() != showUserDefined) { userDefinedPanel.setVisible(showUserDefined); needsResize = true; } if (showUserDefined) { boolean showFrameBFields = interlaceCheckbox.getState(); boolean currentVisibility = paperBLabel.isVisible(); if (currentVisibility != showFrameBFields) { paperBLabel.setVisible(showFrameBFields); paperBField.setVisible(showFrameBFields); inkBLabel.setVisible(showFrameBFields); inkBField.setVisible(showFrameBFields); needsResize = true; } } if (needsResize) { pack(); } }

    // --- Inner Classes ---
    // Preview Worker
    private class PreviewWorker extends SwingWorker<ImageProcessor, Void> { /* ... Same as before ... */ private final PreviewParameters params; private volatile Exception error = null; PreviewWorker(PreviewParameters params) { this.params = params; } @Override protected ImageProcessor doInBackground() throws Exception { long startTime = System.currentTimeMillis(); IJ.showStatus("Processing preview..."); ImageProcessor resultIp = null; ImageProcessor sourceCopy = params.sourceProcessor.duplicate(); try { processImage(sourceCopy, params.blockSizeX, params.blockSizeY, params.isInterlaceEnabled, params.ditheringMode, params.colorMode, params.activeDitherPalette, params.customPalette, params.paperA, params.inkA, params.paperB, params.inkB, params.ditheringLevel, params.brightness, params.contrast, params.gamma, params.brightAttributeThreshold); if (isCancelled()) { return null; } resultIp = sourceCopy; long endTime = System.currentTimeMillis(); IJ.log("Preview processed in " + (endTime - startTime) + " ms."); } catch (Exception e) { error = e; IJ.log("!!! EXCEPTION in PreviewWorker.doInBackground !!!"); e.printStackTrace(); throw e; } finally { IJ.showStatus("Preview ready."); } return resultIp; } @Override protected void done() { if (this != currentWorker) { return; } try { if (isCancelled()) { return; } ImageProcessor resultIp = get(); if (resultIp != null && previewImp != null && previewCanvas != null && paletteCanvas != null) { previewImp.setProcessor(resultIp); previewImp.updateAndDraw(); previewCanvas.repaint(); paletteCanvas.repaint(); } else if(error != null) { IJ.error("Preview Error", "Error during preview processing:\n" + error.getMessage()); } } catch (CancellationException ce) { } catch (Exception e) { error = e; IJ.log("!!! Error during preview task completion or UI update !!!"); e.printStackTrace(); IJ.error("Preview Error", "Error retrieving preview result or updating UI:\n" + e.getMessage()); } finally { if (currentWorker == this) { currentWorker = null; } } } } // End PreviewWorker class
    // Parameter object for the PreviewWorker
    private static class PreviewParameters { /* ... Same as before ... */ final ImageProcessor sourceProcessor; final int blockSizeX, blockSizeY; final DitheringMode ditheringMode; final ColorMode colorMode; final Color[] activeDitherPalette, customPalette; final double ditheringLevel, brightness, contrast, gamma, brightAttributeThreshold; final boolean isInterlaceEnabled; final UserColorSelection paperA, inkA, paperB, inkB; PreviewParameters(ImageProcessor s, int bx, int by, DitheringMode dm, ColorMode cm, Color[] ap, Color[] cp, double dl, double br, double co, double ga, double bt, boolean ie, UserColorSelection pa, UserColorSelection ia, UserColorSelection pb, UserColorSelection ib ) { sourceProcessor=s; blockSizeX=bx; blockSizeY=by; ditheringMode=dm; colorMode=cm; activeDitherPalette=ap; customPalette=cp; ditheringLevel=dl; brightness=br; contrast=co; gamma=ga; brightAttributeThreshold=bt; isInterlaceEnabled=ie; paperA=pa; inkA=ia; paperB=pb; inkB=ib; } } // End PreviewParameters class

